-- 혼동쌍 시드 · published 150건 기준 66쌍
-- relation(idiom_a, idiom_b, rel_type, note)
BEGIN;
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (191, 192, 'confusable', '둘 다 이러지도 저러지도 못함. 유곡은 골짜기에 갇혀 꼼짝 못 하는 쪽이 더 강하다.');  -- 진퇴양난 ↔ 진퇴유곡
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (5, 6, 'confusable', '지통은 원통함 자체, 통한은 원통하고 한스러움까지 포함한다.');  -- 각골지통 ↔ 각골통한
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (127, 85, 'confusable', '안하무인은 남을 업신여기는 태도, 방약무인은 남이 없는 듯 함부로 구는 행동이다.');  -- 안하무인 ↔ 방약무인
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (116, 139, 'confusable', '수수방관은 보고만 있는 것, 오불관언은 아예 상관하지 않겠다는 태도 표명이다.');  -- 수수방관 ↔ 오불관언
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (52, 177, 'confusable', '노심초사는 애를 태우는 것, 전전긍긍은 두려워 떠는 것이다.');  -- 노심초사 ↔ 전전긍긍
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (148, 201, 'confusable', '유유상종은 같은 무리끼리 사귐, 초록동색은 처지가 같아 한편이 됨이다.');  -- 유유상종 ↔ 초록동색
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (155, 9, 'confusable', '이심전심은 말 없이 뜻이 통함, 간담상조는 속마음을 털어놓고 사귐이다.');  -- 이심전심 ↔ 간담상조
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (215, 98, 'confusable', '혈혈단신은 홀몸이라는 상태, 사고무친은 의지할 사람이 없다는 관계다.');  -- 혈혈단신 ↔ 사고무친
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (26, 99, 'confusable', '고립무원은 도움받을 데 없는 처지, 사면초가는 사방이 적에게 둘러싸인 형세다.');  -- 고립무원 ↔ 사면초가
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (110, 182, 'confusable', '설상가상은 나쁜 일이 겹치는 것, 점입가경은 갈수록 더해지는 것이다.');  -- 설상가상 ↔ 점입가경
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (3, 180, 'confusable', '각고면려는 애써 노력함, 절차탁마는 갈고닦아 완성해 감이다.');  -- 각고면려 ↔ 절차탁마
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (39, 86, 'confusable', '군웅할거는 세력 다툼, 백가쟁명은 학설과 주장의 다툼이다.');  -- 군웅할거 ↔ 백가쟁명
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (12, 111, 'confusable', '갑론을박은 서로 반박함, 설왕설래는 말이 오가며 옥신각신함이다.');  -- 갑론을박 ↔ 설왕설래
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (111, 188, 'confusable', '설왕설래는 주고받는 말, 중구난방은 막을 수 없이 여럿이 떠드는 것이다.');  -- 설왕설래 ↔ 중구난방
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (57, 219, 'confusable', '대경실색은 얼굴빛이 변함, 혼비백산은 넋을 잃음이다.');  -- 대경실색 ↔ 혼비백산
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (145, 212, 'confusable', '유구무언은 할 말이 없어 못 하는 것, 함구무언은 알면서 입을 다무는 것이다.');  -- 유구무언 ↔ 함구무언
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (80, 81, 'confusable', '글자는 닮았으나 무위도식은 놀고먹는 것, 무위자연은 자연에 맡기는 삶이다.');  -- 무위도식 ↔ 무위자연
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (168, 170, 'confusable', '자가당착은 앞뒤 말이 모순됨, 자승자박은 제 말에 제가 묶여 곤란해짐이다.');  -- 자가당착 ↔ 자승자박
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (173, 169, 'confusable', '자포자기는 스스로 내던짐, 자격지심은 스스로 미흡하게 여기는 마음이다.');  -- 자포자기 ↔ 자격지심
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (163, 191, 'confusable', '일진일퇴는 나아갔다 물러섰다 하는 것, 진퇴양난은 어느 쪽으로도 못 가는 것이다.');  -- 일진일퇴 ↔ 진퇴양난
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (195, 15, 'confusable', '천양지차는 두 대상의 차이, 격세지감은 시간이 지나 달라진 느낌이다.');  -- 천양지차 ↔ 격세지감
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (70, 71, 'confusable', '만시지탄은 때를 놓친 한탄, 망양지탄은 학문의 길이 갈려 헤매는 한탄이다.');  -- 만시지탄 ↔ 망양지탄
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (71, 74, 'confusable', '망양지탄은 학문의 갈래, 맥수지탄은 나라가 망한 것을 한탄한다.');  -- 망양지탄 ↔ 맥수지탄
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (209, 70, 'confusable', '풍수지탄은 부모를 여읜 뒤의 한탄, 만시지탄은 일반적으로 때를 놓친 한탄이다.');  -- 풍수지탄 ↔ 만시지탄
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (209, 73, 'confusable', '풍수지탄은 부모가 이미 안 계신 슬픔, 망운지정은 멀리 계신 부모를 그리는 마음이다.');  -- 풍수지탄 ↔ 망운지정
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (73, 115, 'confusable', '망운지정은 부모를 그리는 마음, 수구초심은 고향을 그리는 마음이다.');  -- 망운지정 ↔ 수구초심
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (207, 75, 'confusable', '표리부동은 겉과 속이 다른 상태, 면종복배는 앞에서 따르고 뒤에서 배반하는 행동이다.');  -- 표리부동 ↔ 면종복배
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (207, 36, 'confusable', '구밀복검은 말은 달콤하나 속으로 해치려는 것으로, 표리부동보다 악의가 뚜렷하다.');  -- 표리부동 ↔ 구밀복검
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (35, 36, 'confusable', '교언영색은 아첨하는 말과 태도, 구밀복검은 그 속에 해칠 뜻이 있음을 말한다.');  -- 교언영색 ↔ 구밀복검
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (63, 140, 'confusable', '동상이몽은 함께 있으나 속이 다름, 오월동주는 적끼리 한 자리에 있게 된 처지다.');  -- 동상이몽 ↔ 오월동주
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (61, 140, 'confusable', '동병상련은 같은 처지라 가엾게 여김, 오월동주는 적대하는 사이가 함께 있음이다.');  -- 동병상련 ↔ 오월동주
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (7, 119, 'confusable', '각주구검은 변한 상황을 못 보는 것, 수주대토는 요행만 기다리는 것이다.');  -- 각주구검 ↔ 수주대토
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (136, 88, 'confusable', '연목구어는 방법이 틀려 불가능한 것, 백년하청은 아무리 기다려도 안 되는 것이다.');  -- 연목구어 ↔ 백년하청
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (56, 153, 'confusable', '당랑거철은 제 힘을 모르고 덤빔, 이란투석은 약한 것으로 강한 것을 치는 어리석음이다.');  -- 당랑거철 ↔ 이란투석
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (16, 203, 'confusable', '견강부회는 억지로 끌어다 붙임, 침소봉대는 작은 것을 크게 부풀림이다.');  -- 견강부회 ↔ 침소봉대
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (203, 30, 'confusable', '침소봉대는 남에게 부풀려 말함, 과대망상은 스스로 헛되게 믿는 증상이다.');  -- 침소봉대 ↔ 과대망상
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (214, 203, 'confusable', '허장성세는 실속 없이 큰소리침, 침소봉대는 작은 사실을 부풀림이다.');  -- 허장성세 ↔ 침소봉대
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (105, 179, 'confusable', '새옹지마는 앞일을 알 수 없다는 것, 전화위복은 화가 실제로 복이 된 것이다.');  -- 새옹지마 ↔ 전화위복
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (179, 28, 'confusable', '전화위복은 나쁜 일이 좋게 바뀜, 고진감래는 고생 끝에 즐거움이 옴이다.');  -- 전화위복 ↔ 고진감래
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (48, 41, 'confusable', '기사회생은 죽을 뻔하다 살아남, 권토중래는 실패 후 힘을 모아 다시 도전함이다.');  -- 기사회생 ↔ 권토중래
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (33, 220, 'confusable', '괄목상대는 남이 보고 놀랄 만큼 는 것, 환골탈태는 아예 딴사람이 된 것이다.');  -- 괄목상대 ↔ 환골탈태
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (14, 220, 'confusable', '개과천선은 잘못을 고쳐 착해짐, 환골탈태는 사람 자체가 나아진 것이다.');  -- 개과천선 ↔ 환골탈태
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (104, 15, 'confusable', '상전벽해는 세상이 바뀐 사실, 격세지감은 그것을 보고 느끼는 감정이다.');  -- 상전벽해 ↔ 격세지감
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (183, 143, 'confusable', '조변석개는 자주 뜯어고침, 요지부동은 흔들어도 꼼짝 않음. 정반대다.');  -- 조변석개 ↔ 요지부동
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (181, 142, 'confusable', '절치부심은 그 자리의 분한 감정, 와신상담은 오래 참으며 준비하는 것이다.');  -- 절치부심 ↔ 와신상담
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (181, 96, 'confusable', '절치부심은 이를 갈며 속을 썩임, 비분강개는 슬프고 분해 의분이 북받침이다.');  -- 절치부심 ↔ 비분강개
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (93, 96, 'confusable', '분기탱천은 분함이 치솟는 것, 비분강개는 슬픔이 섞인 의분이다.');  -- 분기탱천 ↔ 비분강개
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (49, 191, 'confusable', '기호지세는 그만둘 수 없어 계속 가는 것, 진퇴양난은 어느 쪽도 못 가는 것이다.');  -- 기호지세 ↔ 진퇴양난
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (175, 223, 'confusable', '적반하장은 잘못한 자가 도리어 성내는 행동, 후안무치는 부끄러움을 모르는 성품이다.');  -- 적반하장 ↔ 후안무치
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (205, 11, 'confusable', '토사구팽은 쓸모가 없어지자 버림, 감탄고토는 제 비위에 따라 취하고 버림이다.');  -- 토사구팽 ↔ 감탄고토
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (11, 92, 'confusable', '감탄고토는 제 이익에 따라 태도를 바꿈, 부화뇌동은 줏대 없이 남을 따름이다.');  -- 감탄고토 ↔ 부화뇌동
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (113, 159, 'confusable', '소탐대실은 작은 것을 탐하다 큰 것을 잃음, 일거양득은 하나로 둘을 얻음. 정반대다.');  -- 소탐대실 ↔ 일거양득
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (1, 107, 'confusable', '가렴주구는 권력이 백성을 수탈함, 서절구투는 좀도둑질이다.');  -- 가렴주구 ↔ 서절구투
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (137, 128, 'confusable', '오리무중은 갈피를 못 잡는 상태, 암중모색은 그 속에서 더듬어 찾는 행동이다.');  -- 오리무중 ↔ 암중모색
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (66, 143, 'confusable', '막무가내는 고집을 꺾지 않는 성질, 요지부동은 움직이지 않는 상태다.');  -- 막무가내 ↔ 요지부동
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (224, 70, 'confusable', '후회막급은 뉘우쳐도 소용없음, 만시지탄은 때를 놓친 것을 한탄함이다.');  -- 후회막급 ↔ 만시지탄
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (157, 224, 'confusable', '이왕지사는 이미 지난 일이라는 사실, 후회막급은 그에 대한 뉘우침이다.');  -- 이왕지사 ↔ 후회막급
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (176, 150, 'confusable', '전인미답은 아무도 가 보지 못한 것, 유일무이는 오직 하나뿐인 것이다.');  -- 전인미답 ↔ 유일무이
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (64, 80, 'confusable', '두문불출은 바깥출입을 안 함, 무위도식은 하는 일 없이 놀고먹음이다.');  -- 두문불출 ↔ 무위도식
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (42, 148, 'confusable', '근묵자흑은 물드는 것, 유유상종은 애초에 같은 무리끼리 모이는 것이다.');  -- 근묵자흑 ↔ 유유상종
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (190, 89, 'confusable', '지기지우는 나를 알아주는 벗, 백아절현은 그 벗을 잃은 슬픔이다.');  -- 지기지우 ↔ 백아절현
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (77, 48, 'confusable', '명재경각은 곧 숨이 끊어질 지경, 기사회생은 거기서 다시 살아남이다.');  -- 명재경각 ↔ 기사회생
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (24, 85, 'confusable', '경거망동은 생각 없이 함부로 행동함, 방약무인은 남을 아랑곳하지 않는 태도다.');  -- 경거망동 ↔ 방약무인
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (47, 127, 'confusable', '기고만장은 우쭐하여 뽐냄, 안하무인은 남을 아래로 보는 것이다.');  -- 기고만장 ↔ 안하무인
INSERT OR IGNORE INTO relation (idiom_a, idiom_b, rel_type, note) VALUES (83, 81, 'confusable', '물아일체는 나와 사물이 하나 됨, 무위자연은 꾸밈없이 자연에 맡김이다.');  -- 물아일체 ↔ 무위자연
